class Solution {
  public long maximizeXorAndXor(int[] nums) {
    int n = nums.length, full = (1 << n) - 1;
    int[] andB = new int[full + 1], xorB = new int[full + 1];
    andB[0] = -1;
    int totalXor = 0;
    for (int v : nums) totalXor ^= v;
    long best = 0;
    int[] basis = new int[31];
    for (int mask = 0; mask <= full; mask++) {
      if (mask > 0) {
        int low = Integer.numberOfTrailingZeros(mask);
        andB[mask] = andB[mask & (mask - 1)] & nums[low];
        xorB[mask] = xorB[mask & (mask - 1)] ^ nums[low];
      }
      long andVal = mask == 0 ? 0 : andB[mask];
      int t = totalXor ^ xorB[mask];
      int keep = ~t;
      java.util.Arrays.fill(basis, 0);
      int rest = full ^ mask;
      for (int r = rest; r != 0; r &= r - 1) {
        int x = nums[Integer.numberOfTrailingZeros(r)] & keep;
        for (int b = 30; b >= 0 && x != 0; b--) {
          if ((x >> b & 1) == 0) continue;
          if (basis[b] == 0) {
            basis[b] = x;
            break;
          }
          x ^= basis[b];
        }
      }
      int mx = 0;
      for (int b = 30; b >= 0; b--) if ((mx ^ basis[b]) > mx) mx ^= basis[b];
      best = Math.max(best, andVal + t + 2L * mx);
    }
    return best;
  }
}
